Clase Nodo
    Publico Definir valor Como Entero;
    Publico Definir siguiente Como Nodo;
FinClase

Proceso EjecutarNodoEnlazado
    Definir v1 Como Entero;
    Definir v2 Como Entero;
    Definir primero Como Nodo;
    Definir segundo Como Nodo;
    Leer v1;
    Leer v2;
    primero <- Nuevo Nodo();
    segundo <- Nuevo Nodo();
    primero.valor <- v1;
    segundo.valor <- v2;
    primero.siguiente <- segundo;
    Escribir primero.siguiente.valor;
FinProceso
